INSERT INTO `BiologicalFunctions` VALUES ('protein domain specific binding', 'molecular function', 'protein binding', 'GO:0019904', 'http://purl.obolibrary.org/obo/GO_0019904', 'Interacting selectively and non-covalently with a specific domain of a protein.'), ('molecular function', NULL, 'biological function', 'GO:0003674', 'http://purl.obolibrary.org/obo/GO_0003674', 'Elemental activities, such as catalysis or binding, describing the actions of a gene product at the molecular level. A given gene product may exhibit one or more molecular functions.'), ('RNA 7-methylguanosine cap binding', 'molecular function', 'RNA cap binding', 'GO:0000340', 'http://purl.obolibrary.org/obo/GO_0000340', 'Interacting selectively and non-covalently with the 7-methylguanosine group added cotranscriptionally to the 5'' end of RNA molecules transcribed by polymerase II.'), ('miRNA binding', 'molecular function', 'regulatory RNA binding', 'GO:0035198', 'http://purl.obolibrary.org/obo/GO_0035198', 'Interacting selectively and non-covalently with a microRNA, a 21-23 nucleotide RNA that is processed from a stem-loop RNA precursor (pre-miRNA) that is encoded within plant and animal genomes.'), ('double-stranded RNA binding', 'molecular function', 'RNA binding', 'GO:0003725', 'http://purl.obolibrary.org/obo/GO_0003725', 'Interacting selectively and non-covalently with double-stranded RNA.'), ('nucleic acid binding', 'molecular function', 'heterocyclic compound binding', 'GO:0003676', 'http://purl.obolibrary.org/obo/GO_0003676', 'Interacting selectively and non-covalently with any nucleic acid.'), ('RNA polymerase II complex binding', 'molecular function', 'RNA polymerase core enzyme binding', 'GO:0000993', 'http://purl.obolibrary.org/obo/GO_0000993', 'Interacting selectively and non-covalently with RNA polymerase II core enzyme, a multisubunit eukaryotic nuclear RNA polymerase typically composed of twelve subunits.'), ('RNA polymerase II cis-regulatory region sequence-specific DNA binding', 'molecular function', 'RNA polymerase II transcription regulatory region sequence-specific DNA binding', 'GO:0000978', 'http://purl.obolibrary.org/obo/GO_0000978', 'Interacting selectively and non-covalently with a specific upstream regulatory DNA sequence located in cis relative to the transcription start site of a gene transcribed by RNA polymerase II.');
