INSERT INTO `Biological_Processes` (`description`, `gene_ontology_id`, `exact_match`, `label`, `subclass_of`, `instance_of`) VALUES ('Any process that modulates the frequency, rate or extent of cellular DNA-templated transcription.', 'GO:0006355', 'http://purl.obolibrary.org/obo/GO_0006355', 'regulation of transcription, DNA-templated', 'regulation of gene expression', 'biological process'), ('The chemical reactions and pathways resulting in the breakdown of nuclear-transcribed mRNAs in eukaryotic cells.', 'GO:0000956', 'http://purl.obolibrary.org/obo/GO_0000956', 'nuclear-transcribed mRNA catabolic process', 'mRNA catabolic process', 'biological process'), ('The process in which a solute is transported across a lipid bilayer, from one side of a membrane to the other', 'GO:0055085', 'http://purl.obolibrary.org/obo/GO_0055085', 'transmembrane transport', 'transport', 'biological process'), ('production of new individuals that contain some portion of genetic material inherited from one or more parent organisms', 'GO:0000003', 'http://purl.obolibrary.org/obo/GO_0000003', 'reproduction', 'biological process', 'biological process'), ('biological process whose specific outcome is the progression of a multicellular organism over time from an initial condition (e.g. a zygote or a young adult) to a later condition (e.g. a multicellular animal or an aged adult)', 'GO:0007275', 'http://purl.obolibrary.org/obo/GO_0007275', 'multicellular organism development', 'anatomical structure development', 'biological process'), ('The process whose specific outcome is the progression of an immature germ cell over time, from its formation to the mature structure (gamete). A germ cell is any reproductive cell in a multicellular organism.', 'GO:0007281', 'http://purl.obolibrary.org/obo/GO_0007281', 'germ cell development', 'developmental process involved in reproduction', 'biological process'), ('The process in which small interfering RNAs (siRNAs) direct the cleavage of target mRNAs. Once incorporated into a RNA-induced silencing complex (RISC), a siRNA will typically direct cleavage by base pairing with perfect or near-perfect complementari', 'GO:0090625', 'http://purl.obolibrary.org/obo/GO_0090625', 'mRNA destabilization-mediated gene silencing by siRNA', 'mRNA destabilization', 'biological process'), ('process of formation of spermatozoa germ cells', 'GO:0007283', 'http://purl.obolibrary.org/obo/GO_0007283', 'spermatogenesis', 'male gamete generation', 'biological process'), ('The process whose specific outcome is the progression of the male gonad over time, from its formation to the mature structure.', 'GO:0008584', 'http://purl.obolibrary.org/obo/GO_0008584', 'male gonad development', 'gonad development', 'biological process');
