INSERT INTO (`description`, `gene_ontology_id`, `subclass_of`, `label`, `exact_match`, `instance_of`) VALUES ('The chemical reactions and pathways resulting in the breakdown of mRNA, messenger RNA, which is responsible for carrying the coded genetic ''message'', transcribed from DNA, to sites of protein assembly at the ribosomes.', 'GO:0006402', 'RNA catabolic process', 'mRNA catabolic process', 'http://purl.obolibrary.org/obo/GO_0006402', 'biological process'), ('The import of RNA from the cytoplasm to the nucleus.', 'GO:0006404', 'RNA transport', 'RNA import into nucleus', 'http://purl.obolibrary.org/obo/GO_0006404', 'biological process'), ('The process in which microRNAs (miRNAs) block the translation of target mRNAs into proteins. Once incorporated into a RNA-induced silencing complex (RISC), a miRNA will typically mediate repression of translation if the miRNA imperfectly base-pairs w', 'GO:0035278', 'negative regulation of translation', 'miRNA-mediated gene silencing by inhibition of translation', 'http://purl.obolibrary.org/obo/GO_0035278', 'biological process'), ('Any process that modulates the frequency, rate or extent of addition of phosphate groups into an amino acid in a protein.', 'GO:0001932', 'regulation of protein modification process', 'regulation of protein phosphorylation', 'http://purl.obolibrary.org/obo/GO_0001932', 'biological process'), ('process that prevents the expression of a gene', 'GO:0031047', 'negative regulation of gene expression', 'gene silencing', 'http://purl.obolibrary.org/obo/GO_0031047', 'biological process');
